[
  {
    "id": "90000000-0000-0000-0000-000000000301",
    "title": "A Prayer Book for Soldiers and Sailors",
    "description": "The public-domain text of A Prayer Book for Soldiers and Sailors by Episcopal Church. Army and Navy Commission, preserved across 1 original section with extracted Scripture references.",
    "total_days": 20,
    "tags": [
